class Solution {
public:
    int countUnguarded(int m, int n, std::vector<std::vector<int>>& guards, std::vector<std::vector<int>>& walls) {
        std::vector<std::vector<int>> grid(m, std::vector<int>(n, 0));
        for (const auto& g : guards) grid[g[0]][g[1]] = 1;
        for (const auto& w : walls) grid[w[0]][w[1]] = 2;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (const auto& g : guards) {
            for (int d = 0; d < 4; ++d) {
                int r = g[0] + dirs[d][0], c = g[1] + dirs[d][1];
                while (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] != 1 && grid[r][c] != 2) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                    r += dirs[d][0];
                    c += dirs[d][1];
                }
            }
        }
        int unvisited = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 0) ++unvisited;
            }
        }
        return unvisited;
    }
};

class Solution {
    public int countUnguarded(int m, int n, int[][] guards, int[][] walls) {
        int[][] grid = new int[m][n];
        for (int[] g : guards) grid[g[0]][g[1]] = 1;
        for (int[] w : walls) grid[w[0]][w[1]] = 2;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] g : guards) {
            for (int[] d : dirs) {
                int r = g[0] + d[0], c = g[1] + d[1];
                while (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] != 1 && grid[r][c] != 2) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                    r += d[0];
                    c += d[1];
                }
            }
        }
        int count = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) count++;
            }
        }
        return count;
    }
}

var countUnguarded = function(m, n, guards, walls) {
    const grid = Array.from({ length: m }, () => new Int8Array(n));
    for (const [r, c] of guards) grid[r][c] = 1;
    for (const [r, c] of walls) grid[r][c] = 2;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (const [gr, gc] of guards) {
        for (const [dr, dc] of dirs) {
            let r = gr + dr, c = gc + dc;
            while (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] !== 1 && grid[r][c] !== 2) {
                if (grid[r][c] === 0) grid[r][c] = 3;
                r += dr;
                c += dc;
            }
        }
    }
    let unvisited = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 0) unvisited++;
        }
    }
    return unvisited;
};
